// Fallo no controlado en un workflow de ofertas → Slack + Command Center (cola de atención)
const e = $input.first().json;
const wfName = e.workflow?.name || '';
const SLUGS = [
  [/bankinter/i,'bankinter'],[/caixabank/i,'caixabank'],[/caixapopular/i,'caixa_popular'],[/cr ?arag/i,'cr_aragon'],
  [/cr ?asturias/i,'cr_asturias'],[/cr ?granada/i,'cr_granada'],[/cr ?sur/i,'cr_del_sur'],[/cr ?teruel/i,'cr_teruel'],
  [/deutsche/i,'deutsche_bank'],[/eurocaja/i,'eurocajarural'],[/globalcaja/i,'globalcaja'],[/^ing[_ ]/i,'ing'],
  [/ibercaja/i,'ibercaja'],[/laboral/i,'laboral_kutxa'],[/myinvestor/i,'myinvestor'],[/sabadell/i,'sabadell'],
  [/uci/i,'uci'],[/unicaja/i,'unicaja'],[/santander/i,'santander'],[/kutxabank/i,'kutxabank'],
];
const slug = (SLUGS.find(([re]) => re.test(wfName)) || [])[1] || null;
const execId = e.execution?.id || null;
const url = e.execution?.url || (execId ? `https://huspy.app.n8n.cloud/workflow/${e.workflow?.id}/executions/${execId}` : '');
const msg = String(e.execution?.error?.message || e.trigger?.error?.message || 'Error desconocido').slice(0, 900);
const node = e.execution?.lastNodeExecuted || e.execution?.error?.node?.name || '—';
return [{ json: {
  slack: `🚨 *FALLO WORKFLOW OFERTAS* — ${wfName}\n📍 Nodo: \`${node}\`\n❌ ${msg}\n🔗 <${url}|Ver ejecución>`,
  registro: slug && execId ? {
    bank_slug: slug, source: 'manual', external_id: `n8n-error-${execId}`,
    subject: `Fallo en ${wfName}`, match_status: 'unmatched', classification: 'other', status: 'error',
    error_step: node, error_message: msg, workflow_id: e.workflow?.id, execution_id: execId,
    summary: 'Ejecución fallida sin manejo de error: revisar el correo del banco y procesarlo a mano',
  } : null,
} }];
